import{_ as a,o as t,c as o,a7 as i}from"./chunks/framework.FWlv_suP.js";const h=JSON.parse('{"title":"Radio Bee Data Deletion","description":"Official Data Deletion for Radio Bee.","frontmatter":{"title":"Radio Bee Data Deletion","description":"Official Data Deletion for Radio Bee.","navbar":false,"sidebar":false,"aside":false,"outline":false,"footer":false,"prev":false,"next":false,"editLink":false,"lastUpdated":false,"pageClass":"standalone-policy"},"headers":[],"relativePath":"data-deletion/radio-bee.md","filePath":"data-deletion/radio-bee.md"}'),r={name:"data-deletion/radio-bee.md"};function n(s,e,d,l,c,p){return t(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="delete-radio-bee-data" tabindex="-1">Delete Radio Bee Data <a class="header-anchor" href="#delete-radio-bee-data" aria-label="Permalink to &quot;Delete Radio Bee Data&quot;">​</a></h1><p>Radio Bee does not require an account. Favorites, home-station choices, interface preferences, filters, and cached catalogues are stored locally.</p><h2 id="android-app" tabindex="-1">Android app <a class="header-anchor" href="#android-app" aria-label="Permalink to &quot;Android app&quot;">​</a></h2><p>Open <strong>Android Settings → Apps → Radio Bee → Storage → Clear storage / Clear data</strong>, or uninstall Radio Bee. Exact menu labels may vary by device. This removes locally stored app preferences and cache.</p><h2 id="web-app" tabindex="-1">Web app <a class="header-anchor" href="#web-app" aria-label="Permalink to &quot;Web app&quot;">​</a></h2><p>Open browser settings for <strong>actionanand.github.io</strong> and clear the Radio Bee site&#39;s data and storage. Depending on your browser, clearing the shared site origin may affect other sites hosted on that origin.</p><h2 id="contact-form-submissions" tabindex="-1">Contact form submissions <a class="header-anchor" href="#contact-form-submissions" aria-label="Permalink to &quot;Contact form submissions&quot;">​</a></h2><p>If you previously submitted the optional Google Forms contact form, clearing app data will not erase that submission. To request access, correction, or deletion, email <strong><a href="mailto:anand.official.in@gmail.com" target="_blank" rel="noreferrer">anand.official.in@gmail.com</a></strong> and describe the submission you want reviewed. Requests are handled subject to applicable retention requirements.</p><p>Broadcasters, streaming hosts, and hosting providers independently control their logs and data; deleting Radio Bee&#39;s local data does not delete those external records.</p>',9)])])}const m=a(r,[["render",n]]);export{h as __pageData,m as default};
